using System.Text.Json.Nodes;
string? line;while((line=Console.ReadLine())!=null){var x=JsonNode.Parse(line)!.AsObject();try{var t=x["task"]!.GetValue<string>();JsonObject y=t switch {"ping"=>new JsonObject{["status"]="ready"},"lcs"=>Algorithms.lcs(x),"merge"=>Algorithms.merge(x),"tree"=>Algorithms.tree(x),"naive"=>Algorithms.naive(x),"kmp"=>Algorithms.kmp(x),"rk"=>Algorithms.rk(x),"suffix"=>Algorithms.suffix(x),"aho"=>Algorithms.aho(x),_=>throw new ArgumentException("Unknown task")};Console.WriteLine(y.ToJsonString());}catch(NotImplementedException e){Console.WriteLine(new JsonObject{["error"]=e.Message}.ToJsonString());}}
